<?php $i=$this->getVar('paymentIntent'); $state=$i['state']; $good=$state==='succeeded'; ?>
<section class="payment-workbench"><header><p class="eyebrow">PAYMENT STATUS</p><h1><?=$good?'Payment confirmed':'Checkout update'?></h1></header><div class="payment-status payment-status-<?=htmlspecialchars($state)?>"><strong><?=htmlspecialchars(ucwords(str_replace('_',' ',$state)))?></strong><?php if($state==='awaiting_approval'||$state==='processing'):?><p>We are waiting for a verified response from the payment provider. Access is not granted from a browser return.</p><?php elseif($good):?><p>Your verified payment has been recorded and the related access is being applied.</p><?php elseif(in_array($state,array('refunded','reversed','disputed'),true)):?><p>This payment needs attention. Its latest provider-confirmed state is shown above.</p><?php else:?><p>No access was granted. You can return and try again.</p><?php endif;?></div><div class="chisimba-form-actions"><?php if($good&&$i['purpose_type']==='private_course'):?><a class="button" href="<?=$this->uri(array('action'=>'joincontext','contextcode'=>$i['purpose_id']),'context')?>">Open course</a><?php elseif($state==='awaiting_approval'||$state==='processing'):?><a class="button" href="<?=$this->uri(array('action'=>'return','intent_id'=>$i['id']))?>">Refresh payment status</a><?php endif;?> <a class="button chisimba-button-secondary" href="<?=$this->uri(array())?>">Back to access options</a></div></section>
